class UpdaterRuntime(unittest.TestCase):
 @unittest.skipUnless(shutil.which('javac'),'JDK required')
 def test_dialog_focus_result_timeout_and_retry(self):
  with tempfile.TemporaryDirectory() as d:
   root=Path(d);sources=dict(S);sources['app/blaxyt/mod/AppUpdates.java']=(ROOT/'inject/java/app/blaxyt/mod/AppUpdates.java').read_text(encoding='utf8')
   for name,text in sources.items():
    p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf8')
   subprocess.run(['javac','-encoding','UTF-8','-d',str(root),*[str(root/n) for n in sources]],check=True)
   subprocess.run(['java','-cp',str(root),'app.blaxyt.mod.Check'],check=True)
if __name__=='__main__':unittest.main()
